let mainNav=document.querySelector(".main-nav"),navToggle=mainNav.querySelector(".main-nav__toggle");mainNav.classList.remove("main-nav--nojs"),navToggle.addEventListener("click",(function(){mainNav.classList.contains("main-nav--opened")?mainNav.classList.remove("main-nav--opened"):mainNav.classList.add("main-nav--opened")}));

class CustomSelect {
    constructor(wrapper) {
      this.wrapper = wrapper;
      this.toggle = wrapper.querySelector(".custom-select-toggle");
      this.menu = wrapper.querySelector(".custom-select-menu");
  
      // Hidden input
      this.hiddenInput = document.createElement("input");
      this.hiddenInput.type = "hidden";
      this.hiddenInput.name = this.wrapper.dataset.name || "custom_select";
      this.wrapper.appendChild(this.hiddenInput);
  
      this.registerGlobalClick();
    }
  
    registerGlobalClick() {
      document.addEventListener("click", (e) => {
        if (!this.wrapper.contains(e.target)) {
          this.hideMenu();
        }
      });
    }
  
    hideMenu() {
      this.menu.classList.add("hidden");
    }
  
    showMenu() {
      this.menu.classList.remove("hidden");
    }
  }

  class ColorSelect extends CustomSelect {
    constructor(wrapper) {
      super(wrapper);
      this.options = wrapper.querySelectorAll(".color-options li");
      this.tagsContainer = wrapper.querySelector(".color-tags");
      this.placeholder = wrapper.querySelector(".placeholder");
      this.doneButton = wrapper.querySelector(".tab-done");
  
      this.selectedColors = [];
      this.maxColors = 2;
  
      this.init();
    }
  
    init() {
      this.toggle.addEventListener("click", () => {
        this.menu.classList.toggle("hidden");
      });
  
      this.options.forEach((option) => {
        option.addEventListener("click", () => {
          const color = option.dataset.color;
  
          if (option.classList.contains("selected")) {
            option.classList.remove("selected");
            this.selectedColors = this.selectedColors.filter((c) => c !== color);
          } else {
            if (this.selectedColors.length >= this.maxColors) {
              const removed = this.selectedColors.shift();
              this.wrapper.querySelector(`[data-color="${removed}"]`).classList.remove("selected");
            }
            this.selectedColors.push(color);
            option.classList.add("selected");
          }
  
          this.renderTags();
          this.hiddenInput.value = this.selectedColors.join(",");
        });
      });
  
      this.doneButton.addEventListener("click", () => {
        this.hideMenu();
      });
    }
  
    renderTags() {
      this.tagsContainer.innerHTML = "";
  
      if (this.selectedColors.length === 0) {
        this.placeholder.style.display = "inline";
        return;
      }
  
      this.placeholder.style.display = "none";
  
      this.selectedColors.forEach((color) => {
        const tag = document.createElement("span");
        tag.style.backgroundColor = color;
        this.tagsContainer.appendChild(tag);
      });
    }
  }

  // INIT
document.querySelectorAll(".custom-select-wrapper").forEach((wrapper) => {
    if (wrapper.classList.contains("custom-select--color")) {
      new ColorSelect(wrapper);
    }
  });
